174	<script>
175	  // ===== DOM 参照 =====
176	  const listEl    = document.getElementById('todo-list');
177	  const inputEl   = document.getElementById('new-title');
178	  const addBtn    = document.getElementById('add-btn');
179	  const errorEl   = document.getElementById('error-msg');
180	  const emptyEl   = document.getElementById('empty-msg');
181	
182	  // ===== エラー表示ヘルパー =====
183	  function showError(msg) {
184	    errorEl.textContent = msg;
185	    errorEl.style.display = 'block';
186	  }
187	  function clearError() {
188	    errorEl.style.display = 'none';
189	  }
190	
191	  // ===== 空状態の切り替え =====
192	  function updateEmptyState() {
193	    emptyEl.style.display = listEl.children.length === 0 ? 'block' : 'none';
194	  }
