196	  // ===== 全件取得して画面に描画する =====
197	  async function fetchAndRender() {
198	    const res = await fetch('/todos');
199	    if (!res.ok) { showError('TODO の取得に失敗しました'); return; }
200	    const todos = await res.json();
201	
202	    listEl.innerHTML = '';
203	    todos.forEach(renderItem);
204	    updateEmptyState();
205	  }
206	
207	  // ===== TODO 1件を <li> として追加する =====
208	  function renderItem(todo) {
