1	// jsdom 環境で public/index.html の DOM とロジックをテストする
2	// document.write による再宣言エラーを避けるため、テストごとに new JSDOM() で独立したスコープを作る
3	
4	const { JSDOM } = require('jsdom');
5	const fs = require('fs');
6	const path = require('path');
7	
8	const html = fs.readFileSync(
9	  path.resolve(__dirname, '../../public/index.html'),
10	  'utf-8'
11	);
12	
13	// fetchMock を受け取って新しい JSDOM インスタンスを返す
14	// beforeParse で window.fetch を注入することで、スクリプト実行前にモックが有効になる
15	function createDOM(fetchMock) {
16	  return new JSDOM(html, {
17	    runScripts: 'dangerously',
18	    beforeParse(window) {
19	      window.fetch = fetchMock;
20	    },
21	  });
22	}
23	
24	// レスポンス配列を順番に返す fetch モックを生成する
25	function buildFetchMock(responses) {
26	  let callIndex = 0;
27	  return jest.fn(() => {
28	    const res = responses[callIndex++] ?? responses[responses.length - 1];
29	    return Promise.resolve({
30	      ok: res.ok ?? true,
31	      status: res.status ?? 200,
32	      json: () => Promise.resolve(res.body),
33	    });
34	  });
35	}
36	
37	// 非同期処理（fetch → 描画）が完了するまで待つ
38	const tick = () => new Promise((r) => setTimeout(r, 0));
39	
40	describe('初期表示', () => {
41	  test('起動時に GET /todos が呼ばれる', async () => {
42	    const fetchMock = buildFetchMock([{ body: [] }]);
43	    createDOM(fetchMock);
44	    await tick();
45	
46	    expect(fetchMock).toHaveBeenCalledWith('/todos');
47	  });
48	
49	  test('TODO が空のとき空状態メッセージが表示される', async () => {
50	    const fetchMock = buildFetchMock([{ body: [] }]);
51	    const dom = createDOM(fetchMock);
52	    await tick();
53	
54	    const emptyMsg = dom.window.document.getElementById('empty-msg');
55	    expect(emptyMsg.style.display).not.toBe('none');
56	  });
57	
58	  test('取得した TODO がリストに描画される', async () => {
59	    const fetchMock = buildFetchMock([{
60	      body: [
61	        { id: 1, title: '買い物', completed: false, createdAt: '' },
62	        { id: 2, title: '掃除', completed: true,  createdAt: '' },
63	      ],
64	    }]);
65	    const dom = createDOM(fetchMock);
66	    await tick();
