// jsdom の const 再宣言エラーを避けるため、テストごとに new JSDOM() で独立したスコープを生成する
// beforeParse で window.fetch を注入することで、スクリプト実行前にモックが有効になる

const { JSDOM } = require('jsdom');
const fs   = require('fs');
const path = require('path');

const html = fs.readFileSync(
  path.resolve(__dirname, '../../public/index.html'),
  'utf-8'
);

// ─── ヘルパー ───────────────────────────────────────────────────

function createDOM(fetchMock) {
  return new JSDOM(html, {
    runScripts: 'dangerously',
    beforeParse(window) {
      window.fetch = fetchMock;
    },
  });
}

// responses 配列を順番に返す fetch モックを生成する
function buildFetchMock(responses) {
  let idx = 0;
  return jest.fn(() => {
    const r = responses[idx++] ?? responses[responses.length - 1];
    return Promise.resolve({
      ok:     r.ok   ?? true,
      status: r.status ?? 200,
      json:   () => Promise.resolve(r.body),
    });
  });
}

// fetch → 描画などの非同期処理が完了するまで待つ
const tick = () => new Promise((r) => setTimeout(r, 0));

// テスト用 TODO フィクスチャ
const TODO_A = { id: 1, title: '買い物',   completed: false, createdAt: '' };
const TODO_B = { id: 2, title: '掃除',     completed: true,  createdAt: '' };
const TODO_C = { id: 3, title: '読書',     completed: false, createdAt: '' };

// ─── TODO リストのレンダリング ──────────────────────────────────

describe('TODO リストのレンダリング', () => {
  test('取得した TODO がタイトルとともに全件描画される', async () => {
    // Arrange
    const fetchMock = buildFetchMock([{ body: [TODO_A, TODO_B] }]);

    // Act
    const dom = createDOM(fetchMock);
    await tick();

    // Assert
    const items = dom.window.document.querySelectorAll('.todo-item');
    expect(items).toHaveLength(2);
    expect(items[0].querySelector('.todo-title').textContent).toBe('買い物');
    expect(items[1].querySelector('.todo-title').textContent).toBe('掃除');
  });

  test('未完了 TODO に .completed クラスがなくチェックボックスが unchecked になる', async () => {
    // Arrange
    const fetchMock = buildFetchMock([{ body: [TODO_A] }]);

    // Act
    const dom = createDOM(fetchMock);
    await tick();

    // Assert
    const li       = dom.window.document.querySelector('.todo-item');
    const checkbox = li.querySelector('input[type="checkbox"]');
    expect(li.classList.contains('completed')).toBe(false);
    expect(checkbox.checked).toBe(false);
  });

  test('完了済み TODO に .completed クラスが付きチェックボックスが checked になる', async () => {
    // Arrange
    const fetchMock = buildFetchMock([{ body: [TODO_B] }]);

    // Act
    const dom = createDOM(fetchMock);
    await tick();

    // Assert
    const li       = dom.window.document.querySelector('.todo-item');
    const checkbox = li.querySelector('input[type="checkbox"]');
    expect(li.classList.contains('completed')).toBe(true);
    expect(checkbox.checked).toBe(true);
  });

  test('TODO が空のとき空状態メッセージが表示される', async () => {
    // Arrange
    const fetchMock = buildFetchMock([{ body: [] }]);

    // Act
    const dom = createDOM(fetchMock);
    await tick();

    // Assert
    const emptyMsg = dom.window.document.getElementById('empty-msg');
    expect(emptyMsg.style.display).not.toBe('none');
  });

  test('TODO がある場合は空状態メッセージが非表示になる', async () => {
    // Arrange
    const fetchMock = buildFetchMock([{ body: [TODO_A] }]);

    // Act
    const dom = createDOM(fetchMock);
    await tick();

    // Assert
    const emptyMsg = dom.window.document.getElementById('empty-msg');
    expect(emptyMsg.style.display).toBe('none');
  });

  test('GET 失敗時にエラーメッセージが表示される', async () => {
    // Arrange
    const fetchMock = buildFetchMock([{ ok: false, status: 500, body: {} }]);

    // Act
    const dom = createDOM(fetchMock);
    await tick();

    // Assert
    const errorEl = dom.window.document.getElementById('error-msg');
    expect(errorEl.style.display).toBe('block');
    expect(errorEl.textContent.length).toBeGreaterThan(0);
  });
});

// ─── TODO の追加（POST）────────────────────────────────────────

describe('TODO の追加', () => {
  test('追加ボタンクリックで POST /todos が正しいボディで呼ばれる', async () => {
    // Arrange
    const fetchMock = buildFetchMock([
      { body: [] },                                              // 初期 GET
      { status: 201, body: { ...TODO_A, title: '新タスク' } },  // POST 応答
    ]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act
    dom.window.document.getElementById('new-title').value = '新タスク';
    dom.window.document.getElementById('add-btn').click();
    await tick();

    // Assert
    expect(fetchMock).toHaveBeenCalledWith('/todos', expect.objectContaining({
      method: 'POST',
      body:   JSON.stringify({ title: '新タスク' }),
    }));
  });

  test('POST 成功後に入力欄がクリアされリストに項目が追加される', async () => {
    // Arrange
    const newTodo   = { id: 1, title: '新タスク', completed: false, createdAt: '' };
    const fetchMock = buildFetchMock([
      { body: [] },
      { status: 201, body: newTodo },
    ]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act
    dom.window.document.getElementById('new-title').value = '新タスク';
    dom.window.document.getElementById('add-btn').click();
    await tick();

    // Assert
    expect(dom.window.document.getElementById('new-title').value).toBe('');
    const items = dom.window.document.querySelectorAll('.todo-item');
    expect(items).toHaveLength(1);
    expect(items[0].querySelector('.todo-title').textContent).toBe('新タスク');
  });

  test('Enter キーで POST /todos が呼ばれる', async () => {
    // Arrange
    const fetchMock = buildFetchMock([
      { body: [] },
      { status: 201, body: TODO_C },
    ]);
    const dom   = createDOM(fetchMock);
    await tick();
    const input = dom.window.document.getElementById('new-title');

    // Act
    input.value = '読書';
    const event = new dom.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true });
    input.dispatchEvent(event);
    await tick();

    // Assert
    expect(fetchMock).toHaveBeenCalledWith('/todos', expect.objectContaining({
      method: 'POST',
    }));
  });

  test('タイトルが空のとき POST が呼ばれずエラーが表示される', async () => {
    // Arrange
    const fetchMock = buildFetchMock([{ body: [] }]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act
    dom.window.document.getElementById('new-title').value = '';
    dom.window.document.getElementById('add-btn').click();
    await tick();

    // Assert — 初期 GET の 1 回のみで POST は呼ばれない
    expect(fetchMock).toHaveBeenCalledTimes(1);
    const errorEl = dom.window.document.getElementById('error-msg');
    expect(errorEl.style.display).toBe('block');
  });

  test('POST 失敗時にエラーが表示される', async () => {
    // Arrange
    const fetchMock = buildFetchMock([
      { body: [] },
      { ok: false, status: 400, body: { error: 'title は必須です' } },
    ]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act
    dom.window.document.getElementById('new-title').value = '  ';
    dom.window.document.getElementById('add-btn').click();
    await tick();

    // Assert
    const errorEl = dom.window.document.getElementById('error-msg');
    expect(errorEl.style.display).toBe('block');
    expect(errorEl.textContent).toContain('title は必須です');
  });
});

// ─── 完了チェックボックス（PATCH）─────────────────────────────

describe('完了チェックボックス', () => {
  test('チェックをオンにすると PATCH /todos/:id が completed:true で呼ばれる', async () => {
    // Arrange
    const fetchMock = buildFetchMock([
      { body: [TODO_A] },   // 初期 GET（completed:false）
      { body: { ...TODO_A, completed: true } },  // PATCH 応答
    ]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act
    const checkbox = dom.window.document.querySelector('input[type="checkbox"]');
    checkbox.checked = true;
    checkbox.dispatchEvent(new dom.window.Event('change'));
    await tick();

    // Assert
    expect(fetchMock).toHaveBeenCalledWith(`/todos/${TODO_A.id}`, expect.objectContaining({
      method: 'PATCH',
      body:   JSON.stringify({ completed: true }),
    }));
  });

  test('チェックをオフにすると PATCH /todos/:id が completed:false で呼ばれる', async () => {
    // Arrange
    const fetchMock = buildFetchMock([
      { body: [TODO_B] },   // 初期 GET（completed:true）
      { body: { ...TODO_B, completed: false } },  // PATCH 応答
    ]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act
    const checkbox = dom.window.document.querySelector('input[type="checkbox"]');
    checkbox.checked = false;
    checkbox.dispatchEvent(new dom.window.Event('change'));
    await tick();

    // Assert
    expect(fetchMock).toHaveBeenCalledWith(`/todos/${TODO_B.id}`, expect.objectContaining({
      method: 'PATCH',
      body:   JSON.stringify({ completed: false }),
    }));
  });

  test('チェックをオンにすると li に .completed クラスが付く', async () => {
    // Arrange
    const fetchMock = buildFetchMock([
      { body: [TODO_A] },
      { body: { ...TODO_A, completed: true } },
    ]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act
    const li       = dom.window.document.querySelector('.todo-item');
    const checkbox = li.querySelector('input[type="checkbox"]');
    checkbox.checked = true;
    checkbox.dispatchEvent(new dom.window.Event('change'));
    await tick();

    // Assert
    expect(li.classList.contains('completed')).toBe(true);
  });

  test('PATCH 失敗時にチェックが元に戻りエラーが表示される', async () => {
    // Arrange
    const fetchMock = buildFetchMock([
      { body: [TODO_A] },                        // 初期 GET（completed:false）
      { ok: false, status: 500, body: {} },      // PATCH 失敗
    ]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act — 未完了 TODO のチェックをオンにする
    const checkbox = dom.window.document.querySelector('input[type="checkbox"]');
    checkbox.checked = true;
    checkbox.dispatchEvent(new dom.window.Event('change'));
    await tick();

    // Assert — チェックが false に戻り、エラーが表示される
    expect(checkbox.checked).toBe(false);
    const errorEl = dom.window.document.getElementById('error-msg');
    expect(errorEl.style.display).toBe('block');
  });
});

// ─── 削除ボタン（DELETE）──────────────────────────────────────

describe('削除ボタン', () => {
  test('削除ボタンクリックで DELETE /todos/:id が呼ばれる', async () => {
    // Arrange
    const fetchMock = buildFetchMock([
      { body: [TODO_A] },  // 初期 GET
      { ok: true },        // DELETE 応答
    ]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act
    dom.window.document.querySelector('.delete-btn').click();
    await tick();

    // Assert
    expect(fetchMock).toHaveBeenCalledWith(`/todos/${TODO_A.id}`, expect.objectContaining({
      method: 'DELETE',
    }));
  });

  test('削除成功後に該当アイテムがリストから消える', async () => {
    // Arrange
    const fetchMock = buildFetchMock([
      { body: [TODO_A, TODO_B] },  // 初期 GET（2件）
      { ok: true },                // TODO_A を DELETE
    ]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act — 最初のアイテムを削除する
    dom.window.document.querySelector('.delete-btn').click();
    await tick();

    // Assert
    const items = dom.window.document.querySelectorAll('.todo-item');
    expect(items).toHaveLength(1);
    expect(items[0].querySelector('.todo-title').textContent).toBe('掃除');
  });

  test('最後の 1 件を削除すると空状態メッセージが表示される', async () => {
    // Arrange
    const fetchMock = buildFetchMock([
      { body: [TODO_A] },  // 初期 GET（1件）
      { ok: true },        // DELETE
    ]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act
    dom.window.document.querySelector('.delete-btn').click();
    await tick();

    // Assert
    const emptyMsg = dom.window.document.getElementById('empty-msg');
    expect(emptyMsg.style.display).not.toBe('none');
  });

  test('DELETE 失敗時にエラーが表示されアイテムが残る', async () => {
    // Arrange
    const fetchMock = buildFetchMock([
      { body: [TODO_A] },              // 初期 GET
      { ok: false, status: 404, body: {} },  // DELETE 失敗
    ]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act
    dom.window.document.querySelector('.delete-btn').click();
    await tick();

    // Assert — アイテムは残り、エラーが表示される
    expect(dom.window.document.querySelectorAll('.todo-item')).toHaveLength(1);
    const errorEl = dom.window.document.getElementById('error-msg');
    expect(errorEl.style.display).toBe('block');
  });
});

