    }));
  });

  test('チェックをオンにすると li に .completed クラスが付く', async () => {
    // Arrange
    const fetchMock = buildFetchMock([
      { body: [TODO_A] },
      { body: { ...TODO_A, completed: true } },
    ]);
    const dom = createDOM(fetchMock);
    await tick();

    // Act
    const li       = dom.window.document.querySelector('.todo-item');
